    --border-corner: #5c1010;
    --inset-glow: rgba(139,0,0,0.15);
    --toggle-bg: rgba(10,5,5,0.95);
    --toggle-color: #a23131;
    --toggle-border: #8b0000;
    --label-color: #8b0000;
    --label-dot: #3d1515;
    --val-color: #a3a8b0;
    --tab-inactive: #5c1010;
    --tab-hover: #a23131;
    --tab-active-color: #e0d8d8;
    --tab-active-border: #8b0000;
    --tab-active-glow: rgba(204,0,0,0.4);
    --text-color: #a3a8b0;
    --scrollbar: #3d1515;
    --scrollbar-hover: #5c1010;
    --strong-color: #e0d8d8;
    --strong-glow: rgba(204,0,0,0.2);
    --strong-border: #5c1010;
    --em-color: #ff9fb4;
    --divider-icon: "♰";
    --divider-bg: #0a0505;
    --divider-color: #8b0000;
    --divider-line: #5c1010;
    --corner-border: #5c1010;

    margin: 16px 0; width: 100%; max-width: 550px;
    font-family: 'Noto Serif SC', serif;
    transition: all 0.35s ease;
}

/* ══ 天使变量（白昼🕊️） ══ */
.goth-sys-wrapper[data-theme="angel"] {
    --bg-main: linear-gradient(180deg, rgba(245,249,255,0.98) 0%, rgba(235,243,255,0.99) 100%);
    --bg-main-solid: #f0f6ff;
    --border-color: #7aaee8;
    --border-dim: #b8d4f5;
    --border-corner: #94bfee;
    --inset-glow: rgba(100,160,240,0.08);
    --toggle-bg: rgba(240,247,255,0.98);
    --toggle-color: #3a6fa8;
    --toggle-border: #7aaee8;
    --label-color: #5589c8;
    --label-dot: #b8d4f5;
    --val-color: #4a6888;
    --tab-inactive: #7aaee8;
    --tab-hover: #3a6fa8;
    --tab-active-color: #1a3a5c;
    --tab-active-border: #5589c8;
    --tab-active-glow: rgba(80,140,220,0.3);
    --text-color: #4a6888;
    --scrollbar: #b8d4f5;
    --scrollbar-hover: #7aaee8;
    --strong-color: #1a3a5c;
    --strong-glow: rgba(80,140,220,0.15);
    --strong-border: #b8d4f5;
    --em-color: #8ab4e8;
    --divider-icon: "✦";
    --divider-bg: #f0f6ff;
    --divider-color: #5589c8;
    --divider-line: #b8d4f5;
    --corner-border: #94bfee;
}

/* ══ 天使模式：切换按钮外观 ══ */
.goth-sys-wrapper[data-theme="angel"] .goth-sys-toggle {
    color: #5589c8;
    border-color: #b8d4f5;
}
.goth-sys-wrapper[data-theme="angel"] .goth-sys-toggle:hover {
    background: rgba(100,160,240,0.06);
    color: #3a6fa8;
    box-shadow: inset 0 0 10px rgba(100,160,240,0.1);
}
.goth-sys-wrapper[data-theme="angel"] .goth-sys-toggle.active {
    background: var(--toggle-bg);
    color: var(--toggle-color);
    border-color: var(--toggle-border);
    text-shadow: 0 0 5px rgba(80,140,220,0.3);
}

/* ══ 日夜切换小按钮 ══ */
.goth-theme-btn {
    position: absolute;
    top: 12px; right: 12px;
    font-size: 14px;
    cursor: pointer;
    opacity: 0.55;
    transition: opacity 0.2s ease;
    user-select: none;
    z-index: 10;
}
.goth-theme-btn:hover { opacity: 1; }

/* ══ 主开关按钮 ══ */
.goth-sys-toggle {
    display: inline-flex; align-items: center; gap: 10px;
    font-family: 'Cinzel', 'Noto Serif SC', serif;
    font-size: 0.85rem; font-weight: 700; letter-spacing: 0.15em;
    color: #5c1010; background: transparent;
    border: 1px solid #3d1515; border-radius: 2px;
    padding: 6px 16px; cursor: pointer; transition: all 0.3s ease;
}
.goth-sys-toggle:hover {
    background: rgba(139,0,0,0.05); color: #8b0000;
    box-shadow: inset 0 0 10px rgba(139,0,0,0.1);
}
.goth-sys-toggle.active {
    background: rgba(10,5,5,0.95); color: #a23131;
    border-color: #8b0000; border-bottom: none;
    text-shadow: 0 0 5px rgba(204,0,0,0.4);
}
.goth-toggle-icon { font-size: 1rem; line-height: 1; font-weight: 400; }

/* ══ 主界面框 ══ */
.goth-sys-interface {
    background: var(--bg-main);
    border-top: 2px solid var(--border-color);
    border-bottom: 2px solid var(--border-color);
    padding: 24px; margin-top: -1px;
    box-shadow: inset 0 0 30px var(--inset-glow);
    position: relative; overflow: hidden;
    transition: background 0.35s ease, border-color 0.35s ease, box-shadow 0.35s ease;
}

/* 边角修饰 */
.goth-sys-interface::before, .goth-sys-interface::after {
    content: ''; position: absolute;
    width: 20px; height: 20px;
    border: 1px solid var(--corner-border);
    pointer-events: none;
    transition: border-color 0.35s ease;
}
.goth-sys-interface::before { top: 6px; left: 6px; border-right: none; border-bottom: none; }
.goth-sys-interface::after  { bottom: 6px; right: 6px; border-left: none; border-top: none; }

/* ══ 元数据头部 ══ */
.goth-meta-header {
    display: flex; gap: 24px; flex-wrap: wrap;
    padding-bottom: 20px; margin-bottom: 20px;
    position: relative;
}
.goth-meta-header::after {
    content: var(--divider-icon);
    position: absolute; bottom: -11px; left: 50%;
    transform: translateX(-50%);
    color: var(--divider-color); font-size: 0.95rem;
    background: var(--divider-bg); padding: 0 10px;
    font-family: 'Cinzel', serif;
    text-shadow: 0 0 5px var(--inset-glow);
    transition: color 0.35s ease, background 0.35s ease;
}
.goth-meta-header::before {
    content: ""; position: absolute; bottom: 0; left: 5%; width: 90%; height: 1px;
    background: linear-gradient(90deg, transparent, var(--divider-line), transparent);
    transition: background 0.35s ease;
}

.goth-meta-item {
    display: flex; align-items: flex-start; max-width: 100%;
    font-size: 0.80rem; line-height: 1.6;
}

.goth-label {
    font-family: 'Cinzel', serif; color: var(--label-color);
    font-weight: 700; letter-spacing: 0.15em;
    margin-right: 16px; flex-shrink: 0; position: relative;
    transition: color 0.35s ease;
}
.goth-label::after {
    content: "✦"; font-size: 0.5rem; color: var(--label-dot);
    position: absolute; right: -10px; top: 2px;
    transition: color 0.35s ease;
}

.g-val {
    color: var(--val-color); letter-spacing: 0.05em;
    word-break: break-word;
    transition: color 0.35s ease;
}

/* ══ 导航标签 ══ */
.goth-nav-tabs {
    display: flex; gap: 20px; margin-bottom: 20px;
    overflow-x: auto; padding-bottom: 2px;
}
.goth-nav-tabs::-webkit-scrollbar { display: none; }

.goth-tab-btn {
    font-family: 'Cinzel', serif; font-size: 0.85rem; font-weight: 700;
    color: var(--tab-inactive); letter-spacing: 0.1em;
    cursor: pointer; padding: 4px 0 6px 0;
    border-bottom: 2px solid transparent; transition: all 0.2s ease;
    white-space: nowrap;
}
.goth-tab-btn:hover { color: var(--tab-hover); }
.goth-tab-btn.active {
    color: var(--tab-active-color);
    border-bottom-color: var(--tab-active-border);
    text-shadow: 0 0 8px var(--tab-active-glow);
}

/* ══ 阅读视窗 ══ */
.goth-viewport {
    height: 300px; overflow-y: auto; padding-right: 12px;
    font-size: 0.9rem; color: var(--text-color);
    line-height: 1.8; white-space: pre-wrap;
    word-break: break-word; text-align: justify;
    transition: color 0.35s ease;
}
.goth-viewport::-webkit-scrollbar { width: 4px; }
.goth-viewport::-webkit-scrollbar-track { background: transparent; }
.goth-viewport::-webkit-scrollbar-thumb {
    background: var(--scrollbar); border-radius: 2px;
    transition: background 0.35s ease;
}
.goth-viewport::-webkit-scrollbar-thumb:hover { background: var(--scrollbar-hover); }

/* ══ 面板动画 ══ */
.goth-panel { display: none; animation: goth-fade 0.4s ease forwards; }
.goth-panel.active { display: block; }
@keyframes goth-fade {
    from { opacity: 0; transform: translateY(4px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ══ 正文排版 ══ */
.goth-panel b, .goth-panel strong {
    color: var(--strong-color); font-weight: 900;
    text-shadow: 0 2px 4px rgba(0,0,0,0.3), 0 0 8px var(--strong-glow);
    border-bottom: 1px solid var(--strong-border);
    transition: color 0.35s ease, border-color 0.35s ease;
}
.goth-panel em, .goth-panel i {
    color: var(--em-color); font-style: italic; font-weight: 300;
    transition: color 0.35s ease;
}
</style>

<script>
setTimeout(() => {
    document.querySelectorAll('.goth-sys-wrapper:not([data-init="true"])').forEach(wrapper => {
        let rawData = wrapper.querySelector('.goth-raw-data');
        if (rawData) {
            let match = rawData.innerHTML.match(/<serial>\s*(.*?)\s*<\/serial>/i);
            let titleText = (match && match[1]) ? 'Scene ' + match[1] : '档案附录';
            let textEl = wrapper.querySelector('.goth-toggle-text');
            if (textEl) textEl.innerText = titleText;
            wrapper.dataset.title = titleText;
        }
        wrapper.dataset.init = "true";
    });
}, 50);

if (!window.toggleGothTheme) {
    window.toggleGothTheme = function(btn) {
        let wrapper = btn.closest('.goth-sys-wrapper');
        let toggleIcon = wrapper.querySelector('.goth-toggle-icon');
        if (wrapper.dataset.theme === 'angel') {
            wrapper.dataset.theme = '';
            btn.innerText = '🦇';
            if (toggleIcon && !wrapper.querySelector('.goth-sys-toggle').classList.contains('active')) {
                toggleIcon.innerText = '♰';
            }
        } else {
            wrapper.dataset.theme = 'angel';
            btn.innerText = '🕊️';
            if (toggleIcon && !wrapper.querySelector('.goth-sys-toggle').classList.contains('active')) {
                toggleIcon.innerText = '✦';
            }
        }
    };
}

if (!window.toggleGothSys) {
    window.toggleGothSys = function(btn) {
        let wrapper = btn.closest('.goth-sys-wrapper');
        let uiBox = wrapper.querySelector('.goth-sys-interface');
        let icon = btn.querySelector('.goth-toggle-icon');
        let text = btn.querySelector('.goth-toggle-text');
        let originalTitle = wrapper.dataset.title || '档案附录';
        let isAngel = wrapper.dataset.theme === 'angel';

        if (uiBox.style.display === 'none') {
            uiBox.style.display = 'block';
            btn.classList.add('active');
            icon.innerText = "✦";
            text.innerText = "CLOSE";
        } else {
            uiBox.style.display = 'none';
            btn.classList.remove('active');
            icon.innerText = isAngel ? '✦' : '♰';
            text.innerText = originalTitle;
            return;
        }

        if (wrapper.dataset.parsed === "true") return;

        let rawData = wrapper.querySelector('.goth-raw-data');
        let tempDiv = document.createElement('div');
        tempDiv.innerHTML = rawData.innerHTML;

        let headerBox = wrapper.querySelector('.goth-meta-header');
        let hasMeta = false;

        let metaConfigs = [
            { selector: 'serial', targetClass: '.i-serial' },
            { selector: 'scene',  targetClass: '.i-loc' },
            { selector: 'time',   targetClass: '.i-time' }
        ];

        metaConfigs.forEach(cfg => {
            let el = tempDiv.querySelector(cfg.selector);
            if (el && el.innerText.trim() !== '') {
                let targetNode = wrapper.querySelector(cfg.targetClass);
                targetNode.querySelector('.g-val').innerHTML = el.innerHTML;
                targetNode.style.display = 'flex';
                hasMeta = true;
                el.remove();
            }
        });

        if (hasMeta) headerBox.style.display = 'flex';

        const sections = [
            { tag: 'snapshot', name: 'SNAPSHOT' },
            { tag: 'abstract', name: 'ABSTRACT' },
            { tag: 'todo',     name: 'TO-DO' },
            { tag: 'seeds',    name: 'SEEDS' },
            { tag: 'events',   name: 'EVENTS' }
        ];

        let navTabs = wrapper.querySelector('.goth-nav-tabs');
        let contentArea = wrapper.querySelector('.goth-content-area');
        let isFirst = true;

        sections.forEach(sec => {
            let el = tempDiv.querySelector(sec.tag);
            if (el) {
                let tabBtn = document.createElement('div');
                tabBtn.className = 'goth-tab-btn' + (isFirst ? ' active' : '');
                tabBtn.innerText = sec.name;

                let panel = document.createElement('div');
                panel.className = 'goth-panel' + (isFirst ? ' active' : '');
                panel.innerHTML = el.innerHTML.trim();

                tabBtn.onclick = function(e) {
                    e.stopPropagation();
                    navTabs.querySelectorAll('.goth-tab-btn').forEach(b => b.classList.remove('active'));
                    contentArea.querySelectorAll('.goth-panel').forEach(p => p.classList.remove('active'));
                    tabBtn.classList.add('active');
                    panel.classList.add('active');
                };

                navTabs.appendChild(tabBtn);
                contentArea.appendChild(panel);
                isFirst = false;
            }
        });

        wrapper.dataset.parsed = "true";
    };
}
</script>

</div>

</body>
</html>
